/** autogenerated **/
Ext._define('rh.socialsecurity.SocialSecurityManage', {
    extend: 'toolkit.widget.TabPanel',

	socialsecurity: function(value, dispatch){
		dispatch = core.nullValue(dispatch, true);

		if(value !== undefined){
			this._socialsecurity = value;

			if(dispatch) this.observerSS();
		}
		else
			return this._socialsecurity;
	},

	observerSS: function() {
		if(this.socialsecurity()){
			this.getSocialSecurityRangeGrid().enable();
			this.getSocialSecurityRangeGrid().setParam('socialsecurity', this.socialsecurity());
			this.getSocialSecurityRangeGrid().setFilterProperty('socialsecurity_id', this.socialsecurity(), 100);
		}
		else{
			this.getSocialSecurityRangeGrid().disable();
			this.getSocialSecurityRangeGrid().getStore().removeAll();
			this.getSocialSecurityRangeGrid().setFilterProperty('socialsecurity_id', 0, 100, false);
		}
    },

    getSocialSecurityGrid: function() {
        if(!this._grid) {
            this._grid = Ext._create('rh.socialsecurity.SocialSecurityGrid', {
                region: 'center',
                minHeight: 300,
                gridAutoLoad: true
            });
			this._grid.getSelectionModel().on({
				scope: this,
				rowselect: function(sm, index, data){
					this.socialsecurity(data.get('pk'));
				},
				rowdeselect: function(){
					this.socialsecurity(null);
				},
			});
        }

        return this._grid;
    },

	getSocialSecurityRangeGrid: function() {
	    if(!this._rangesGrid)
	        this._rangesGrid = Ext._create('rh.socialsecurity.SocialSecurityRangeGrid', {
	        	id: 'rh.socialsecurity.SocialSecurityRangeGrid',
	        	region: 'south',
				minHeight: 300,
				height: 400,
				split: true,
				gridAutoLoad: false
	        });

	    return this._rangesGrid;
	},

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Tabelas Previdenciárias'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getSocialSecurityGrid(),
                    this.getSocialSecurityRangeGrid()
                ]
            }
        );

        rh.socialsecurity.SocialSecurityManage.superclass.constructor.call(this, cfg);
    }
});
